schemas.schema-01-systematic.prisma:
/// System-wide configuration entries stored as independent key-value
/// records. Used to toggle features, define thresholds, or set URIs across
/// the platform. This table is intentionally decoupled from domain content
/// and identities to avoid dependency cycles. Managed primarily by
/// administrators through configuration UIs or scripts; referenced by
/// runtime services to read current settings. No foreign keys are declared
/// to other domains.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique configuration identifier (e.g., "public_read",
  /// "attachments.max_count"). Serves as the business key for lookups.
  key String

  /// String value for this configuration when applicable. Only one of the
  /// typed value columns is expected to be used per row.
  value_string String?

  /// Integer value for this configuration when applicable (e.g., numeric
  /// limits).
  value_int Int? @db.Integer

  /// Decimal value for this configuration when applicable (e.g., thresholds or
  /// ratios).
  value_double Float? @db.DoublePrecision

  /// Boolean value for this configuration when applicable (e.g., feature
  /// toggle).
  value_boolean Boolean?

  /// URI value for this configuration when applicable (e.g., callback URLs,
  /// CDN endpoints).
  value_uri String? @db.VarChar(80000)

  /// Human-readable explanation of the configuration purpose and usage.
  description String?

  /// Optional timestamp indicating when this configuration became effective.
  effective_since DateTime? @db.Timestamptz

  /// Creation timestamp (UTC).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (UTC).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for retention and operational safety.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([created_at])
  @@index([effective_since, created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System policies governing platform behavior such as public-read,
/// moderation defaults, and feature switches. Each policy is an
/// independently managed record with an optional effective window. This
/// table is maintained by administrators and does not reference domain
/// content directly. Related changes are recorded in {@link
/// civic_board_audit_logs}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Stable policy identifier (e.g., "public_read", "attachments.policy",
  /// "report.duplicate_cooldown_hours"). Unique across the system.
  policy_code String

  /// Human-friendly policy name for administrative UIs.
  name String

  /// Optional category for grouping related policies (e.g., "visibility",
  /// "attachments", "reporting").
  category String?

  /// Whether the policy is currently enabled. For value-carrying policies,
  /// this indicates if enforcement is active.
  enabled Boolean

  /// Optional string value carried by the policy (e.g., textual rule).
  value_string String?

  /// Optional integer value (e.g., max counts, cooldown hours).
  value_int Int? @db.Integer

  /// Optional decimal value (e.g., size limits in MB with fractional
  /// precision).
  value_double Float? @db.DoublePrecision

  /// Optional start of the policy’s effective window (UTC).
  starts_at DateTime? @db.Timestamptz

  /// Optional end of the policy’s effective window (UTC).
  ends_at DateTime? @db.Timestamptz

  /// Administrative notes describing policy rationale or change context (not
  /// shown to end users).
  notes String?

  /// Creation timestamp (UTC).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (UTC).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for retention and operational safety.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([policy_code])
  @@index([enabled, created_at])
  @@index([category, created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Append-only audit trail capturing security- and compliance-relevant
/// events across the system. Records the acting entity (user/admin/system),
/// optional session context, target reference, action name, outcome, and
/// request metadata. Designed for historical analysis and investigations;
/// not intended for direct user manipulation. This table provides the
/// system’s audit history for changes in {@link civic_board_policies} and
/// {@link civic_board_configurations}, as well as domain operations.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Type of actor that initiated the event (e.g., "user", "admin", "system").
  /// Stored as raw text to avoid cross-domain foreign keys.
  actor_type String

  /// Identifier of the actor, when applicable. Stored without a foreign key to
  /// avoid domain coupling.
  actor_id String? @db.Uuid

  /// Identifier of the actor session when applicable. Stored without a foreign
  /// key to avoid domain coupling.
  actor_session_id String? @db.Uuid

  /// Business action name (e.g., "post.create", "comment.delete",
  /// "policy.update").
  action String

  /// Outcome summary (e.g., "success", "failure:rate_limited").
  outcome String

  /// Target table name when the action is scoped to a resource (e.g.,
  /// "civic_board_posts").
  target_table String?

  /// Target resource identifier when applicable. Stored without foreign key to
  /// avoid coupling.
  target_id String? @db.Uuid

  /// IP address observed for the request context, when available.
  ip String?

  /// Full request URL, when available.
  href String? @db.VarChar(80000)

  /// Referrer URL, when available.
  referrer String? @db.VarChar(80000)

  /// Optional human-readable message or error context to aid investigations.
  message String?

  /// Event creation timestamp (UTC).
  created_at DateTime @db.Timestamptz

  /// Timestamp for any administrative update (e.g., redaction). Normally equal
  /// to created_at for immutable entries.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for retention or legal hold workflows.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([created_at])
  @@index([actor_type, actor_id, created_at])
  @@index([target_table, target_id, created_at])
  @@index([action(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([outcome(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([message(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Operational store for rate limiting windows and counters per actor and
/// scope. Managed by the system to enforce anti-abuse policies (e.g.,
/// post/comment/report creation, login attempts). Records are
/// created/updated within short time windows and expired/cleaned by
/// background tasks. No foreign keys to identities to avoid cross-domain
/// coupling.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_rate_limits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Logical action scope for the rate limit (e.g., "post.create",
  /// "comment.create", "report.create", "login.failed").
  scope String

  /// Actor type constrained by business logic (e.g., "user", "admin", "ip").
  /// Stored as text to avoid cross-domain keys.
  actor_type String

  /// Identifier of the actor when applicable (e.g., user/admin). For IP-scoped
  /// limits, this may be a surrogate or left null if not applicable.
  actor_id String? @db.Uuid

  /// Start timestamp (UTC) of the rate limit window represented by this record.
  window_started_at DateTime @db.Timestamptz

  /// End timestamp (UTC) of the rate limit window represented by this record.
  window_ends_at DateTime @db.Timestamptz

  /// Number of actions performed during the window at the time of update.
  count Int @db.Integer

  /// Enforced maximum actions allowed during the window per actor and scope.
  limit Int @db.Integer

  /// Record creation timestamp (UTC).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (UTC).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp to permit safe retention before purge.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  @@unique([scope, actor_type, actor_id, window_started_at], map: "civic_board_rate_limits_scope_actor_type_actor_id_wind_d9db7562")
  @@index([actor_type, actor_id, created_at])
  @@index([scope, created_at])
  @@index([window_ends_at, created_at])
  @@index([scope(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Registered member accounts for the civicBoard application. Stores
/// authentication credentials and profile-facing display attributes. Serves
/// as the primary identity for regular users who author posts and comments.
/// Related entities include session records {@link
/// civic_board_user_sessions} and verification/reset flows via {@link
/// civic_board_email_verification_of_users} and {@link
/// civic_board_password_reset_token_of_users}.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Login and contact email for the user. Must be unique across all users and
  /// used for verification workflows.
  email String

  /// BCrypt or similar password hash for authentication. Never store plain
  /// passwords.
  password_hash String

  /// Public display name shown on authored content instead of email for
  /// privacy.
  display_name String

  /// Whether the user’s email has been verified. Governs posting/commenting
  /// eligibility.
  email_verified Boolean

  /// Whether the account is currently suspended and restricted from creating
  /// or modifying content.
  suspended Boolean

  /// Timestamp when the account was suspended, if applicable.
  suspended_at DateTime? @db.Timestamptz

  /// Record creation time (UTC).
  created_at DateTime @db.Timestamptz

  /// Last update time (UTC).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion time (UTC). Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  civic_board_user_sessions civic_board_user_sessions[]
  civic_board_email_verification_of_users civic_board_email_verification_of_users[]
  civic_board_password_reset_token_of_users civic_board_password_reset_token_of_users[]
  civic_board_posts civic_board_posts[]
  civic_board_post_attachments civic_board_post_attachments[]
  civic_board_comments civic_board_comments[]
  civic_board_report_of_posts civic_board_report_of_posts[]
  civic_board_report_of_comments civic_board_report_of_comments[]
  civic_board_post_reactions civic_board_post_reactions[]
  civic_board_comment_reactions civic_board_comment_reactions[]

  @@unique([email])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Authenticated session records for {@link civic_board_users}. Follows the
/// exact session table pattern: one actor FK, connection context (ip, href,
/// referrer), created_at, and optional expired_at. Managed through
/// authentication flows for audit and authorization context.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged user’s {@link civic_board_users.id}
  civic_board_user_id String @db.Uuid

  /// IP address observed when establishing the session.
  ip String

  /// Full URL that initiated the session (connection URL).
  href String @db.VarChar(80000)

  /// Referrer URL captured at session creation.
  referrer String @db.VarChar(80000)

  /// Session creation time (UTC).
  created_at DateTime @db.Timestamptz

  /// Session expiration/end time (UTC), when present.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user civic_board_users @relation(fields: [civic_board_user_id], references: [id], onDelete: Cascade)

  civic_board_posts civic_board_posts[]
  civic_board_post_attachments civic_board_post_attachments[]
  civic_board_comments civic_board_comments[]
  civic_board_report_of_posts civic_board_report_of_posts[]
  civic_board_report_of_comments civic_board_report_of_comments[]

  @@index([civic_board_user_id, created_at])
}

