  report      civic_board_reports       @relation(fields: [civic_board_report_id], references: [id], onDelete: Cascade)
  comment     civic_board_comments      @relation(fields: [civic_board_comment_id], references: [id], onDelete: Cascade)
  user        civic_board_users         @relation(fields: [civic_board_user_id], references: [id], onDelete: Cascade)
  userSession civic_board_user_sessions @relation(fields: [civic_board_user_session_id], references: [id], onDelete: Cascade)

  @@unique([civic_board_report_id])
  // spellchecker: ignore-next-line
  @@unique([civic_board_user_id, civic_board_comment_id], map: "civic_board_report_of_comments_civic_board_user_id_civ_5ad90d4a")
  @@index([civic_board_user_session_id])
  // spellchecker: ignore-next-line
  @@index([civic_board_comment_id, created_at], map: "civic_board_report_of_comments_civic_board_comment_id__dd9c5e79")
  // spellchecker: ignore-next-line
  @@index([civic_board_user_id, created_at], map: "civic_board_report_of_comments_civic_board_user_id_cre_74764add")
}

/// Administrative resolution records for {@link civic_board_reports}.
/// Captures the acting admin and session with the chosen decision (Hide,
/// Delete, or No Action) and an optional note. Enforces a single resolution
/// per report via a unique FK, creating an immutable audit trail separate
/// from content state changes.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Resolved report's {@link civic_board_reports.id}. One action per report.
  civic_board_report_id String @db.Uuid

  /// Acting administrator's {@link civic_board_admins.id}.
  civic_board_admin_id String @db.Uuid

  /// Administrator session's {@link civic_board_admin_sessions.id}.
  civic_board_admin_session_id String @db.Uuid

  /// Resolution outcome string such as "No Action", "Hide", or "Delete".
  decision String

  /// Optional moderator note providing rationale for the decision.
  outcome_note String?

  /// Creation timestamp (UTC) when the moderation action was recorded.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (UTC) for this moderation action record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (UTC) if the action record is withdrawn
  /// administratively.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  report       civic_board_reports        @relation(fields: [civic_board_report_id], references: [id], onDelete: Cascade)
  admin        civic_board_admins         @relation(fields: [civic_board_admin_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  adminSession civic_board_admin_sessions @relation(fields: [civic_board_admin_session_id], references: [id], onDelete: Cascade, map: "civic_board_moderation_actions_civic_board_admin_sessi_57b87bba")

  @@unique([civic_board_report_id])
  // spellchecker: ignore-next-line
  @@index([civic_board_admin_id, created_at], map: "civic_board_moderation_actions_civic_board_admin_id_cr_92d62d40")
  @@index([civic_board_admin_session_id])
  @@index([created_at])
}

schemas.schema-05-reactions.prisma:
/// User single-like reactions on posts. Each row represents at most one
/// reaction per (user, post) pair. The reaction is considered active when
/// not soft-deleted (deleted_at is NULL). Designed to support toggle
/// semantics by updating timestamps while preserving auditability.
/// References {@link civic_board_users} as the reacting actor and {@link
/// civic_board_posts} as the target content. Hidden or Deleted targets must
/// block new reactions at the application layer; self-like is prevented by
/// business rules.
///
/// @namespace Reactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_post_reactions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reacting user's {@link civic_board_users.id}.
  civic_board_user_id String @db.Uuid

  /// Target post's {@link civic_board_posts.id}.
  civic_board_post_id String @db.Uuid

  /// Creation timestamp when the reaction was first added (Like on).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp, including toggling operations.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp representing Like off toggle. NULL means the
  /// reaction is currently active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user civic_board_users @relation(fields: [civic_board_user_id], references: [id], onDelete: Cascade)
  post civic_board_posts @relation(fields: [civic_board_post_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@unique([civic_board_user_id, civic_board_post_id], map: "civic_board_post_reactions_civic_board_user_id_civic_b_29e43a18")
  @@index([civic_board_post_id, created_at])
  @@index([civic_board_user_id, created_at])
  @@index([civic_board_post_id, deleted_at])
}

/// User single-like reactions on comments. Each row represents at most one
/// reaction per (user, comment) pair. The reaction is active when deleted_at
/// is NULL, enabling toggle behavior without losing history. References
/// {@link civic_board_users} as the reacting actor and {@link
/// civic_board_comments} as the target comment. Hidden or Deleted targets
/// must block new reactions at the application layer; self-like is prevented
/// by business rules.
///
/// @namespace Reactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_comment_reactions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reacting user's {@link civic_board_users.id}.
  civic_board_user_id String @db.Uuid

  /// Target comment's {@link civic_board_comments.id}.
  civic_board_comment_id String @db.Uuid

  /// Creation timestamp when the reaction was first added (Like on).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp, including toggling operations.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp representing Like off toggle. NULL means the
  /// reaction is currently active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user    civic_board_users    @relation(fields: [civic_board_user_id], references: [id], onDelete: Cascade)
  comment civic_board_comments @relation(fields: [civic_board_comment_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@unique([civic_board_user_id, civic_board_comment_id], map: "civic_board_comment_reactions_civic_board_user_id_civi_dc820f7b")
  // spellchecker: ignore-next-line
  @@index([civic_board_comment_id, created_at], map: "civic_board_comment_reactions_civic_board_comment_id_c_ecc7af57")
  // spellchecker: ignore-next-line
  @@index([civic_board_user_id, created_at], map: "civic_board_comment_reactions_civic_board_user_id_crea_277aee69")
  // spellchecker: ignore-next-line
  @@index([civic_board_comment_id, deleted_at], map: "civic_board_comment_reactions_civic_board_comment_id_d_37b50b96")
}

/// Administrative policy controlling whether reactions are enabled and under
/// what constraints. This table allows feature toggling and guardrails such
/// as self-like prohibition and per-user rate limits. It is managed
/// independently by admins and referenced by application logic at runtime.
/// Does not denormalize any computed counters. Related entities: users
/// {@link civic_board_users} for ownership context if needed; targets are
/// {@link civic_board_posts} and {@link civic_board_comments}.
///
/// @namespace Reactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civic_board_reaction_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Human-readable policy code identifier (e.g., "default"). Used to select
  /// the active configuration.
  code String

  /// Whether reactions feature is globally enabled.
  enabled Boolean

  /// Whether reactions are permitted on posts.
  allow_on_posts Boolean

  /// Whether reactions are permitted on comments.
  allow_on_comments Boolean

  /// Whether self-like is permitted. Should remain false to satisfy product
  /// rules.
  allow_self_like Boolean

  /// Optional cap on the number of reactions a single user may add per
  /// calendar day. NULL means unlimited per this policy.
  max_reactions_per_user_per_day Int? @db.Integer

  /// Creation timestamp of this policy row.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of this policy row.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for deprecated or replaced policies. NULL means
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([created_at])
}

