import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICivicBoardPasswordResetTokenOfUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPasswordResetTokenOfUser";

/**
 * Confirming a password reset using invalid tokens should be rejected.
 *
 * Business context:
 *
 * - Password reset confirmation consumes a previously issued token to set a new
 *   credential. Invalid, expired, or already-used tokens must be rejected
 *   without revealing sensitive details.
 *
 * Test steps:
 *
 * 1. Generate a nominal new password.
 * 2. Prepare multiple invalid token strings (random/uuid-like/short/prefixed).
 * 3. For each token, call confirmPasswordReset and assert that it throws.
 *
 * Notes:
 *
 * - We do not verify HTTP status codes or error bodies; only failure occurrence.
 * - We cannot directly observe credential changes with the given API surface, so
 *   we scope validation to rejecting invalid tokens.
 */
export async function test_api_user_password_reset_confirm_invalid_token(
  connection: api.IConnection,
) {
  // 1) Nominal new password value
  const newPassword: string = RandomGenerator.alphaNumeric(12);

  // 2) Multiple malformed/invalid token shapes
  const tokens: string[] = [
    RandomGenerator.alphaNumeric(48),
    typia.random<string & tags.Format<"uuid">>(),
    `invalid-${RandomGenerator.alphabets(8)}`,
    "x",
  ];

  // 3) Each invalid token must cause the confirmation to fail
  await ArrayUtil.asyncForEach(tokens, async (token, index) => {
    await TestValidator.error(
      `reject invalid reset token #${index + 1}`,
      async () => {
        await api.functional.auth.user.password.reset.confirm.confirmPasswordReset(
          connection,
          {
            body: {
              token,
              password: newPassword,
            } satisfies ICivicBoardPasswordResetTokenOfUser.IConfirm,
          },
        );
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserPassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserPassword";

/**
 * Change password successfully and validate session behavior.
 *
 * End-to-end workflow:
 *
 * 1. Join a new member to obtain authenticated context (SDK sets Authorization).
 * 2. Change password with correct current password and strong new password.
 * 3. Validate result summary (ok=true, revoked_sessions=0 as there are no other
 *    sessions).
 * 4. Ensure current session remains valid by changing password again using the
 *    newly set password as current_password (should succeed).
 * 5. Confirm password rotation by attempting to change password using the old (now
 *    invalid) current password (should fail).
 */
export async function test_api_user_password_change_success(
  connection: api.IConnection,
) {
  // 1) Register a new member (authenticated context)
  const currentPassword1: string = RandomGenerator.alphaNumeric(12);
  const newPassword1: string = RandomGenerator.alphaNumeric(16);
  const newPassword2: string = RandomGenerator.alphaNumeric(18);

  const email: string = typia.random<string & tags.Format<"email">>();
  const href: string = typia.random<
    string & tags.MinLength<1> & tags.MaxLength<80000> & tags.Format<"uri">
  >();

  const authorized = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: currentPassword1,
      display_name: RandomGenerator.name(),
      ip: null,
      href,
      referrer: "",
    } satisfies ICivicBoardUser.ICreate,
  });
  typia.assert(authorized);
  if (authorized.user !== undefined)
    TestValidator.predicate(
      "newly joined account is not suspended",
      authorized.user.suspended === false,
    );

  // 2) Change password with correct current password
  const summary1 = await api.functional.auth.user.password.updatePassword(
    connection,
    {
      body: {
        current_password: currentPassword1,
        new_password: newPassword1,
      } satisfies ICivicBoardUserPassword.IUpdate,
    },
  );
  typia.assert(summary1);
  TestValidator.predicate(
    "first password change should succeed",
    summary1.ok === true,
  );
  TestValidator.equals(
    "no other sessions should be revoked on first change",
    summary1.revoked_sessions,
    0,
  );

  // 3) Attempt to change again using the old (now invalid) current password -> should fail
  await TestValidator.error(
    "changing with old password should fail after rotation",
    async () => {
      await api.functional.auth.user.password.updatePassword(connection, {
        body: {
          current_password: currentPassword1, // old password (invalid now)
          new_password: RandomGenerator.alphaNumeric(14),
        } satisfies ICivicBoardUserPassword.IUpdate,
      });
    },
  );

  // 4) Current session remains valid: change again using the new password as current
  const summary2 = await api.functional.auth.user.password.updatePassword(
    connection,
    {
      body: {
        current_password: newPassword1,
        new_password: newPassword2,
      } satisfies ICivicBoardUserPassword.IUpdate,
    },
  );
  typia.assert(summary2);
  TestValidator.predicate(
    "second password change (with new current password) should succeed",
    summary2.ok === true,
  );
  TestValidator.equals(
    "no other sessions should be revoked on second change as well",
    summary2.revoked_sessions,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICivicBoardPasswordResetToken } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPasswordResetToken";
import type { ICivicBoardPasswordResetTokenOfAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPasswordResetTokenOfAdmin";

/**
 * Validate privacy-preserving acknowledgement for non-existent admin email
 * password reset requests.
 *
 * Business goal
 *
 * - Ensure that requesting a password reset for an admin email that does not
 *   exist returns a generic acknowledgement without revealing account
 *   existence.
 * - Verify consistent uniform responses across repeated attempts with the same
 *   email.
 *
 * Steps
 *
 * 1. Generate a random admin email (assumed unissued in the system).
 * 2. Call POST /auth/admin/password/reset/request with that email.
 * 3. Validate the response structure (typia.assert) and business rule
 *    (acknowledged === true).
 * 4. Repeat the request with the same email and confirm acknowledgements are
 *    consistent.
 */
export async function test_api_admin_password_reset_request_nonexistent_email_privacy_acknowledgement(
  connection: api.IConnection,
) {
  // 1) Generate a unique, likely non-existent admin email
  const email = typia.random<string & tags.Format<"email">>();

  // 2) First request
  const first: ICivicBoardPasswordResetToken.ISummary =
    await api.functional.auth.admin.password.reset.request.requestPasswordReset(
      connection,
      {
        body: { email } satisfies ICivicBoardPasswordResetTokenOfAdmin.ICreate,
      },
    );
  // Validate response type (ensures no sensitive leakage beyond ISummary contract)
  typia.assert(first);
  // Business logic: acknowledged should be true regardless of account existence
  TestValidator.equals("first request acknowledged", first.acknowledged, true);

  // 3) Repeat the same request to confirm uniform behavior
  const second: ICivicBoardPasswordResetToken.ISummary =
    await api.functional.auth.admin.password.reset.request.requestPasswordReset(
      connection,
      {
        body: { email } satisfies ICivicBoardPasswordResetTokenOfAdmin.ICreate,
      },
    );
  typia.assert(second);
  TestValidator.equals(
    "repeat request acknowledged remains true",
    second.acknowledged,
    true,
  );

  // 4) Consistency check across attempts (do not bind to expires_at presence/value)
  TestValidator.equals(
    "consistent acknowledgement across attempts",
    second.acknowledged,
    first.acknowledged,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPost";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";
import type { IECivicBoardContentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardContentStatus";
import type { IECivicBoardPostStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardPostStatus";

/**
 * Verify that a non-owner cannot soft-delete another user's civic board post.
 *
 * Business goal: Ownership enforcement on the user-scoped delete endpoint.
 *
 * Steps:
 *
 * 1. Join as User A and obtain authorization
 * 2. Create a post as User A and validate author matches User A
 * 3. Join as User B (different account) to switch authentication context
 * 4. Attempt to delete User A's post as User B and expect an error
 *
 * Notes:
 *
 * - SDK handles Authorization header updates on join(); do not touch headers.
 * - No specific HTTP status code validation (only error existence).
 * - No read-back endpoint provided; state verification is limited to the negative
 *   authorization attempt.
 */
export async function test_api_post_soft_delete_by_non_owner_forbidden(
  connection: api.IConnection,
) {
  // 1) Join as User A (author)
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userAHrefRaw = typia.random<string & tags.Format<"uri">>();
  const userAHref = typia.assert<
    string & tags.Format<"uri"> & tags.MinLength<1>
  >(userAHrefRaw);
  const userADisplayRaw = RandomGenerator.name(1);
  const userADisplay = typia.assert<
    string & tags.MinLength<1> & tags.MaxLength<120>
  >(userADisplayRaw);

  const userA = await api.functional.auth.user.join(connection, {
    body: {
      email: userAEmail,
      password: "P@ssw0rd!",
      display_name: userADisplay,
      href: userAHref,
      referrer: "",
    } satisfies ICivicBoardUser.ICreate,
  });
  typia.assert(userA);

  // 2) Create a post as User A
  const titleSource = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 10,
  });
  // Ensure length <= 120 while preserving non-whitespace content
  const titleTrimmed = titleSource.substring(0, 120).trim() || "Title";
  const title = typia.assert<
    string &
      tags.MinLength<1> &
      tags.MaxLength<120> &
      tags.Pattern<"^(?=.*\\S)[\\s\\S]{1,120}$">
  >(titleTrimmed);

  const bodySource = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 6,
    sentenceMax: 12,
    wordMin: 3,
    wordMax: 10,
  });
  const bodyText = typia.assert<
    string &
      tags.MinLength<1> &
      tags.MaxLength<20000> &
      tags.Pattern<"^(?=.*\\S)[\\s\\S]{1,20000}$">
  >(bodySource);

  const post = await api.functional.civicBoard.user.posts.create(connection, {
    body: {
      title,
      body: bodyText,
    } satisfies ICivicBoardPost.ICreate,
  });
  typia.assert(post);

  // Validate the post is authored by User A
  TestValidator.equals(
    "created post author should be User A",
    post.author.id,
    userA.id,
  );

  // 3) Join as User B (non-owner)
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userBHrefRaw = typia.random<string & tags.Format<"uri">>();
  const userBHref = typia.assert<
    string & tags.Format<"uri"> & tags.MinLength<1>
  >(userBHrefRaw);
  const userBDisplayRaw = RandomGenerator.name(1);
  const userBDisplay = typia.assert<
    string & tags.MinLength<1> & tags.MaxLength<120>
  >(userBDisplayRaw);

  const userB = await api.functional.auth.user.join(connection, {
    body: {
      email: userBEmail,
      password: "P@ssw0rd!",
      display_name: userBDisplay,
      href: userBHref,
      referrer: "",
    } satisfies ICivicBoardUser.ICreate,
  });
  typia.assert(userB);

  // 4) Attempt to delete User A's post as User B → should fail
  await TestValidator.error(
    "non-owner cannot soft-delete another user's post",
    async () => {
      await api.functional.civicBoard.user.posts.erase(connection, {
        postId: post.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardAdmin";
import type { ICivicBoardAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardAdminJoin";
import type { ICivicBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardConfiguration";

/**
 * Delete-once then confirm repeated deletion fails for configurations.
 *
 * Purpose:
 *
 * - Ensure configuration erase endpoint is NOT idempotent for already-deleted
 *   rows.
 * - After a successful soft-delete, repeating DELETE on the same key must fail
 *   with a not-available outcome (verified via generic error expectation).
 *
 * Steps:
 *
 * 1. Admin self-registers (join) to acquire privileges and token context.
 * 2. Create a configuration using a unique business key.
 * 3. First DELETE succeeds for the configuration key.
 * 4. Second DELETE must throw an error (already removed/not available).
 * 5. Validate key integrity and error behavior without inspecting status codes.
 */
export async function test_api_configuration_erase_already_deleted(
  connection: api.IConnection,
) {
  // 1) Authenticate as admin (self-join)
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<
        string & tags.MinLength<3> & tags.MaxLength<320> & tags.Format<"email">
      >(),
      password: typia.random<
        string & tags.MinLength<8> & tags.MaxLength<2000>
      >(),
      display_name: typia.random<
        string & tags.MinLength<1> & tags.MaxLength<120>
      >(),
      href: typia.random<
        string & tags.MinLength<1> & tags.MaxLength<80000> & tags.Format<"uri">
      >(),
      referrer: typia.random<
        string & tags.MinLength<1> & tags.MaxLength<80000> & tags.Format<"uri">
      >(),
      // ip is optional; omit to let server derive it
    } satisfies ICivicBoardAdminJoin.ICreate,
  });
  typia.assert(admin);

  // 2) Create a configuration with a unique key (boolean variant)
  const key: string = `e2e.${RandomGenerator.alphaNumeric(12)}`;
  const created = await api.functional.civicBoard.admin.configurations.create(
    connection,
    {
      body: {
        key,
        value_boolean: true,
      } satisfies ICivicBoardConfiguration.ICreate,
    },
  );
  typia.assert(created);
  TestValidator.equals(
    "created configuration key matches intended key",
    created.key,
    key,
  );

  // 3) First DELETE should succeed (void response)
  await api.functional.civicBoard.admin.configurations.erase(connection, {
    configurationKey: key,
  });

  // 4) Second DELETE must fail: not-available for already-removed key
  await TestValidator.error(
    "second deletion on the same configuration must fail",
    async () => {
      await api.functional.civicBoard.admin.configurations.erase(connection, {
        configurationKey: key,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";

/**
 * Validate successful user session refresh after self-signup.
 *
 * Workflow:
 *
 * 1. Join a brand-new member to obtain initial authorized payload (access/refresh
 *    tokens)
 * 2. Refresh using the returned refresh token
 * 3. Validate identity continuity and practical token usability signals
 *
 * Notes:
 *
 * - We do not validate refresh rotation semantics; only success and continuity
 * - We do not touch connection.headers; SDK manages Authorization propagation
 */
export async function test_api_user_session_refresh_success(
  connection: api.IConnection,
) {
  // 1) Create a new user (self-signup) to establish an active session
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd!",
    display_name: RandomGenerator.name(2),
    // Explicitly allow null ip to follow optional context semantics
    ip: null,
    href: `https://app.example.com/${RandomGenerator.alphaNumeric(12)}`,
    referrer: `https://ref.example.com/${RandomGenerator.alphaNumeric(10)}`,
  } satisfies ICivicBoardUser.ICreate;

  const joined: ICivicBoardUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: joinBody });
  typia.assert(joined);

  // If server provided a user summary, its id must match the authorized id
  if (joined.user !== undefined) {
    TestValidator.equals(
      "summary id equals authorized id",
      joined.user.id,
      joined.id,
    );
  }

  // 2) Refresh using the refresh token from the joined session
  const refreshBody = {
    refresh_token: joined.token.refresh,
  } satisfies ICivicBoardUserSession.IRequest;

  const refreshed: ICivicBoardUser.IAuthorized =
    await api.functional.auth.user.refresh(connection, { body: refreshBody });
  typia.assert(refreshed);

  // 3) Business validations
  // Identity continuity: id should persist across join -> refresh
  TestValidator.equals(
    "refreshed id equals joined id",
    refreshed.id,
    joined.id,
  );

  // Practical usability signals: non-empty token strings after refresh
  TestValidator.predicate(
    "refreshed access token must be non-empty",
    refreshed.token.access.length > 0,
  );
  TestValidator.predicate(
    "refreshed refresh token must be non-empty",
    refreshed.token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";

/**
 * Deny refresh after logout (expired session semantics).
 *
 * This test ensures a refresh attempt fails once the member logs out and the
 * server marks the session as expired (civic_board_user_sessions.expired_at).
 *
 * Steps:
 *
 * 1. Join as a new member to obtain access + refresh artifacts (active session).
 * 2. Call logout to terminate the current session (expired_at is set).
 * 3. Attempt refresh with the previously issued refresh_token and expect an error.
 *
 * Validations:
 *
 * - All successful responses are type-asserted with typia.assert().
 * - Logout summary belongs to the joined user.
 * - Logout marks the session expired (expired_at is not null/undefined).
 * - Refresh after logout throws (no token issuance for expired session).
 */
export async function test_api_user_session_refresh_after_logout_denied(
  connection: api.IConnection,
) {
  // 1) Join: create a new member and obtain tokens bound to an active session
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(1),
    ip: null,
    href: typia.random<
      string & tags.Format<"uri"> & tags.MinLength<1> & tags.MaxLength<80000>
    >(),
    referrer: typia.random<
      string & tags.Format<"uri"> & tags.MinLength<1> & tags.MaxLength<80000>
    >(),
  } satisfies ICivicBoardUser.ICreate;
  const authorized: ICivicBoardUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: joinBody });
  typia.assert(authorized);

  const refreshToken: string = authorized.token.refresh;

  // 2) Logout: terminate the current session
  const sessionSummary: ICivicBoardUserSession.ISummary =
    await api.functional.auth.user.logout(connection);
  typia.assert(sessionSummary);

  // Business validations on logout
  TestValidator.equals(
    "logout summary belongs to joined user",
    sessionSummary.user.id,
    authorized.id,
  );
  TestValidator.predicate(
    "session is marked expired after logout",
    sessionSummary.expired_at !== null &&
      sessionSummary.expired_at !== undefined,
  );

  // 3) Refresh attempt using the previously issued refresh token must fail
  await TestValidator.error(
    "refresh must be denied after logout (expired session)",
    async () => {
      const refreshBody = {
        refresh_token: refreshToken,
      } satisfies ICivicBoardUserSession.IRequest;
      await api.functional.auth.user.refresh(connection, { body: refreshBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICivicBoardEmailVerificationOfUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardEmailVerificationOfUser";

/**
 * Ensure unauthenticated users cannot request email verification issuance.
 *
 * Business rule:
 *
 * - POST /auth/user/email/verify/request requires an authenticated session and
 *   binds issuance to the current civic_board_users.id.
 * - Anonymous callers must be rejected and no token should be issued.
 *
 * Steps:
 *
 * 1. Create an unauthenticated connection (headers: {}). Do not otherwise touch
 *    headers.
 * 2. Invoke the endpoint with a minimal valid body ({} satisfies IRequest).
 * 3. Expect an error (authorization enforced). Do not assert specific HTTP status
 *    codes.
 * 4. If the SDK is in simulate mode, skip the negative test because simulator does
 *    not enforce auth and returns random data.
 */
export async function test_api_email_verification_request_unauthenticated_denied(
  connection: api.IConnection,
) {
  // Simulator mode cannot enforce authorization; skip negative path under simulate.
  if (connection.simulate === true) {
    TestValidator.predicate(
      "skip unauthenticated denial test under simulator mode",
      true,
    );
    return;
  }

  // 1) Prepare unauthenticated connection (allowed pattern: create new connection with empty headers)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // 2) Minimal valid body: IRequest with no delivery hints
  const body = {} satisfies ICivicBoardEmailVerificationOfUser.IRequest;

  // 3) Expect authorization error for unauthenticated call
  await TestValidator.error(
    "unauthenticated users cannot request email verification",
    async () => {
      await api.functional.auth.user.email.verify.request.requestEmailVerification(
        unauthConn,
        { body },
      );
