import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPost";
import type { ICivicBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPostAttachment";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";
import type { IECivicBoardAttachmentContentType } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardAttachmentContentType";
import type { IECivicBoardContentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardContentStatus";
import type { IECivicBoardPostStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardPostStatus";

export async function test_api_post_attachment_public_retrieval(
  connection: api.IConnection,
) {
  /**
   * Validate public retrieval of attachment metadata for a Published post.
   *
   * Steps:
   *
   * 1. Join a user (authorized context)
   * 2. Create a post (business rule: Published on success)
   * 3. Register an attachment under the post
   * 4. Retrieve the attachment without authentication (public)
   * 5. Validate immutable metadata and visibility inheritance
   */

  // 1) Join a user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: `P@ssw0rd-${RandomGenerator.alphaNumeric(8)}`,
    display_name: RandomGenerator.name(1),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: `https://app.example.com/${RandomGenerator.alphaNumeric(8)}`,
    referrer: `https://example.com/${RandomGenerator.alphaNumeric(6)}`,
  } satisfies ICivicBoardUser.ICreate;
  const authorized: ICivicBoardUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: joinBody });
  typia.assert(authorized);

  // 2) Create a Published post
  const postBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 5,
      sentenceMax: 12,
      wordMin: 3,
      wordMax: 8,
    }),
  } satisfies ICivicBoardPost.ICreate;
  const post: ICivicBoardPost =
    await api.functional.civicBoard.user.posts.create(connection, {
      body: postBody,
    });
  typia.assert(post);
  TestValidator.equals(
    "post is created in Published status",
    post.status,
    "Published",
  );

  // 3) Register an attachment under the post
  const imageTypes = ["image/jpeg", "image/png", "image/gif"] as const;
  const chosenType: (typeof imageTypes)[number] =
    RandomGenerator.pick(imageTypes);
  const attachmentCreateBody = {
    uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(24)}`,
    original_filename: `file_${RandomGenerator.alphabets(8)}.${chosenType.split("/")[1]}`,
    content_type: chosenType,
    byte_size: 204800,
    image_width: 800,
    image_height: 600,
  } satisfies ICivicBoardPostAttachment.ICreate;
  const created: ICivicBoardPostAttachment =
    await api.functional.civicBoard.user.posts.attachments.create(connection, {
      postId: post.id,
      body: attachmentCreateBody,
    });
  typia.assert(created);
  TestValidator.equals(
    "attachment belongs to the created post",
    created.civic_board_post_id,
    post.id,
  );
  TestValidator.equals(
    "attachment uploader matches the joined user",
    created.uploader.id,
    authorized.id,
  );

  // 4) Public retrieval without authentication
  const publicConn: api.IConnection = { ...connection, headers: {} };
  const read: ICivicBoardPostAttachment =
    await api.functional.civicBoard.posts.attachments.at(publicConn, {
      postId: post.id,
      attachmentId: created.id,
    });
  typia.assert(read);

  // 5) Validations on immutable metadata and visibility
  TestValidator.equals("fetched attachment id matches", read.id, created.id);
  TestValidator.equals(
    "fetched attachment parent id matches",
    read.civic_board_post_id,
    post.id,
  );
  TestValidator.equals("uri is immutable", read.uri, created.uri);
  TestValidator.equals(
    "original filename is immutable",
    read.original_filename,
    created.original_filename,
  );
  TestValidator.equals(
    "content type is preserved",
    read.content_type,
    created.content_type,
  );
  TestValidator.equals(
    "byte size is preserved",
    read.byte_size,
    created.byte_size,
  );
  TestValidator.equals(
    "image width is preserved",
    read.image_width ?? null,
    created.image_width ?? null,
  );
  TestValidator.equals(
    "image height is preserved",
    read.image_height ?? null,
    created.image_height ?? null,
  );
  TestValidator.equals(
    "uploader id is consistent",
    read.uploader.id,
    created.uploader.id,
  );
  TestValidator.predicate(
    "active attachments must not be soft-deleted (deleted_at null or undefined)",
    read.deleted_at === null || read.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPost";
import type { ICivicBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPostAttachment";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";
import type { IECivicBoardAttachmentContentType } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardAttachmentContentType";
import type { IECivicBoardContentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardContentStatus";
import type { IECivicBoardPostStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardPostStatus";
import type { IESortOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IESortOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageICivicBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICivicBoardPostAttachment";

export async function test_api_post_attachments_search_and_filter(
  connection: api.IConnection,
) {
  // 1) Member joins (no login). SDK will attach Authorization header automatically.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: `Pw_${RandomGenerator.alphaNumeric(12)}`,
    display_name: RandomGenerator.name(2),
    href: "https://app.example.com/" + RandomGenerator.alphabets(8),
    referrer: "",
  } satisfies ICivicBoardUser.ICreate;
  const authorized = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(authorized);

  // 2) Create a post (Published by business rule on creation)
  const postBody = {
    title: RandomGenerator.paragraph({ sentences: 5 }),
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 8,
      sentenceMax: 16,
    }),
  } satisfies ICivicBoardPost.ICreate;
  const post: ICivicBoardPost =
    await api.functional.civicBoard.user.posts.create(connection, {
      body: postBody,
    });
  typia.assert(post);

  // 3) Upload multiple diverse attachments under the post
  type Spec = {
    filename: string;
    contentType: IECivicBoardAttachmentContentType;
    size: number;
    width?: number | null;
    height?: number | null;
    ext: string;
  };
  const specs: Spec[] = [
    {
      filename: `photo_${RandomGenerator.alphabets(6)}`,
      contentType: "image/jpeg",
      size: 125_000,
      width: 1024,
      height: 768,
      ext: ".jpg",
    },
    {
      filename: `scan_${RandomGenerator.alphabets(6)}`,
      contentType: "application/pdf",
      size: 980_000,
      width: null,
      height: null,
      ext: ".pdf",
    },
    {
      filename: `diagram_${RandomGenerator.alphabets(6)}`,
      contentType: "image/png",
      size: 240_000,
      width: 800,
      height: 600,
      ext: ".png",
    },
    {
      filename: `sheet_${RandomGenerator.alphabets(6)}`,
      contentType: "application/pdf",
      size: 2_400_000,
      width: null,
      height: null,
      ext: ".pdf",
    },
    {
      filename: `anim_${RandomGenerator.alphabets(6)}`,
      contentType: "image/gif",
      size: 540_000,
      width: 640,
      height: 480,
      ext: ".gif",
    },
    {
      filename: `photo_${RandomGenerator.alphabets(6)}`,
      contentType: "image/jpeg",
      size: 320_000,
      width: 1280,
      height: 720,
      ext: ".jpg",
    },
  ];

  const created: ICivicBoardPostAttachment[] = [];
  for (let i = 0; i < specs.length; i++) {
    const s = specs[i];
    const body = {
      uri: `https://files.example.com/${s.filename}${s.ext}`,
      original_filename: `${s.filename}${s.ext}`,
      content_type: s.contentType,
      byte_size: s.size,
      image_width: s.width ?? null,
      image_height: s.height ?? null,
    } satisfies ICivicBoardPostAttachment.ICreate;
    const att = await api.functional.civicBoard.user.posts.attachments.create(
      connection,
      { postId: post.id, body },
    );
    typia.assert(att);
    created.push(att);
  }

  // Build an unauthenticated connection to verify public access
  const publicConn: api.IConnection = { ...connection, headers: {} };

  // Common helpers
  const idsOf = (rows: ICivicBoardPostAttachment.ISummary[]): string[] =>
    rows.map((r) => r.id);
  const ensureAllBelongToPost = (rows: ICivicBoardPostAttachment.ISummary[]) =>
    rows.every((r) => r.civic_board_post_id === post.id);

  // 4-A) Filter: images only (content_types) + sort by original_filename ASC
  const imageTypes: IECivicBoardAttachmentContentType[] = [
    "image/jpeg",
    "image/png",
    "image/gif",
  ];
  const imagesExpected = created.filter((c) =>
    imageTypes.includes(c.content_type),
  );
  const listImages = await api.functional.civicBoard.posts.attachments.index(
    publicConn,
    {
      postId: post.id,
      body: {
        content_types: imageTypes,
        order_by: "original_filename",
        order_direction: "asc",
        limit: 100,
        page: 1,
      } satisfies ICivicBoardPostAttachment.IRequest,
    },
  );
  typia.assert(listImages);

  TestValidator.predicate(
    "images-only filter returns only images",
    listImages.data.every((r) => imageTypes.includes(r.content_type)),
  );
  TestValidator.predicate(
    "all results belong to target post (images-only)",
    ensureAllBelongToPost(listImages.data),
  );
  // Ascending by original_filename
  TestValidator.predicate(
    "sorted by original_filename asc (images-only)",
    listImages.data.every(
      (r, i, a) => i === 0 || a[i - 1].original_filename <= r.original_filename,
    ),
  );
  // Ensure expected created images are present (limit=100 to avoid truncation)
  const returnedImageIds = new Set(idsOf(listImages.data));
  TestValidator.predicate(
    "all created image attachments are included in listing",
    imagesExpected.every((e) => returnedImageIds.has(e.id)),
  );

  // 4-B) Filter: original_filename_contains (case-insensitive)
  const targetForName = created[0];
  const needle = targetForName.original_filename.slice(
    1,
    Math.min(6, targetForName.original_filename.length),
  );
  const listByName = await api.functional.civicBoard.posts.attachments.index(
    publicConn,
    {
      postId: post.id,
      body: {
        original_filename_contains: needle,
        order_by: "original_filename",
        order_direction: "asc",
        limit: 100,
        page: 1,
      } satisfies ICivicBoardPostAttachment.IRequest,
    },
  );
  typia.assert(listByName);

  TestValidator.predicate(
    "filename substring filter matches",
    listByName.data.every((r) =>
      r.original_filename.toLowerCase().includes(needle.toLowerCase()),
    ),
  );
  TestValidator.predicate(
    "all results belong to target post (name filter)",
    ensureAllBelongToPost(listByName.data),
  );

  // 4-C) Filter: byte_size range and sort by byte_size DESC
  const sizes = created.map((c) => c.byte_size).sort((a, b) => a - b);
  const byteMin = sizes.length >= 2 ? sizes[1] : sizes[0];
  const byteMax = sizes.length >= 2 ? sizes[sizes.length - 2] : sizes[0];
  const listBySize = await api.functional.civicBoard.posts.attachments.index(
    publicConn,
    {
      postId: post.id,
      body: {
        byte_size_min: byteMin,
        byte_size_max: byteMax,
        order_by: "byte_size",
        order_direction: "desc",
        limit: 100,
        page: 1,
      } satisfies ICivicBoardPostAttachment.IRequest,
    },
  );
  typia.assert(listBySize);

  TestValidator.predicate(
    "byte_size range respected",
    listBySize.data.every(
      (r) => r.byte_size >= byteMin && r.byte_size <= byteMax,
    ),
  );
  TestValidator.predicate(
    "sorted by byte_size desc",
    listBySize.data.every(
      (r, i, a) => i === 0 || a[i - 1].byte_size >= r.byte_size,
    ),
  );
  TestValidator.predicate(
    "all results belong to target post (size filter)",
    ensureAllBelongToPost(listBySize.data),
  );

  // 4-D) Pagination stability: consistent ordering and non-overlap across pages
  const page1 = await api.functional.civicBoard.posts.attachments.index(
    publicConn,
    {
      postId: post.id,
      body: {
        order_by: "original_filename",
        order_direction: "asc",
        limit: 2,
        page: 1,
      } satisfies ICivicBoardPostAttachment.IRequest,
    },
  );
  typia.assert(page1);

  const page2 = await api.functional.civicBoard.posts.attachments.index(
    publicConn,
    {
      postId: post.id,
      body: {
        order_by: "original_filename",
        order_direction: "asc",
        limit: 2,
        page: 2,
      } satisfies ICivicBoardPostAttachment.IRequest,
    },
  );
  typia.assert(page2);

  TestValidator.predicate(
    "no overlap between page 1 and page 2 (by original_filename asc)",
    page1.data.every((x) => page2.data.every((y) => y.id !== x.id)),
  );
  TestValidator.predicate(
    "ordered asc by original_filename across pages",
    [
      ...page1.data.map((r) => r.original_filename),
      ...page2.data.map((r) => r.original_filename),
    ].every((v, i, a) => i === 0 || a[i - 1] <= v),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICivicBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPost";
import type { ICivicBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardPostAttachment";
import type { ICivicBoardUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUser";
import type { ICivicBoardUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICivicBoardUserSession";
import type { IECivicBoardAttachmentContentType } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardAttachmentContentType";
import type { IECivicBoardContentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardContentStatus";
import type { IECivicBoardPostStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IECivicBoardPostStatus";

/**
 * Ensure attachment update is blocked when parent post is soft-deleted.
 *
 * Steps:
 *
 * 1. User self-joins (authentication established by SDK automatically).
 * 2. User creates a civic board post.
 * 3. User uploads an attachment under that post.
 * 4. User soft-deletes the parent post.
 * 5. User attempts to update the attachment under the deleted post.
 * 6. Expect an error (denial) and validate no further side effects.
 *
 * Notes:
 *
 * - We validate relational integrity at creation time by checking the
 *   attachment's civic_board_post_id equals the created post id.
 * - No GET endpoint is provided for post-erase verification of attachment state,
 *   so we only assert the business rule denial via error on update.
 */
export async function test_api_post_attachment_update_blocked_on_deleted_post(
  connection: api.IConnection,
) {
  // 1) User self-join (authentication). Token management is auto-handled by SDK
  const joinBody = typia.random<ICivicBoardUser.ICreate>();
  const auth = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(auth);

  // 2) Create a civic board post
  const postBody = {
    title: typia.random<
      string &
        tags.MinLength<1> &
        tags.MaxLength<120> &
        tags.Pattern<"^(?=.*\\S)[\\s\\S]{1,120}$">
    >(),
    body: typia.random<
      string &
        tags.MinLength<1> &
        tags.MaxLength<20000> &
        tags.Pattern<"^(?=.*\\S)[\\s\\S]{1,20000}$">
    >(),
  } satisfies ICivicBoardPost.ICreate;
  const post = await api.functional.civicBoard.user.posts.create(connection, {
    body: postBody,
  });
  typia.assert(post);

  // 3) Upload an attachment under the created post
  const allowedTypes = [
    "image/jpeg",
    "image/png",
    "image/gif",
    "application/pdf",
  ] as const;
  const pickedType = RandomGenerator.pick(allowedTypes);
  const imageWidth = pickedType.startsWith("image/")
    ? typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>()
    : null;
  const imageHeight = pickedType.startsWith("image/")
    ? typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>()
    : null;
  const createAttachmentBody = {
    uri: typia.random<string & tags.MaxLength<80000> & tags.Format<"uri">>(),
    original_filename: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<120>
    >(),
    content_type: pickedType,
    byte_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    image_width: imageWidth,
    image_height: imageHeight,
  } satisfies ICivicBoardPostAttachment.ICreate;
  const attachment =
    await api.functional.civicBoard.user.posts.attachments.create(connection, {
      postId: post.id,
      body: createAttachmentBody,
    });
  typia.assert(attachment);

  // Relational integrity check at creation time
  TestValidator.equals(
    "attachment belongs to the created post",
    attachment.civic_board_post_id,
    post.id,
  );

  // 4) Soft-delete the parent post
  await api.functional.civicBoard.user.posts.erase(connection, {
    postId: post.id,
  });

  // 5) Prepare an update attempt under the deleted parent
  const updateBody = {
    uri: typia.random<string & tags.MaxLength<80000> & tags.Format<"uri">>(),
    original_filename: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<120>
    >(),
  } satisfies ICivicBoardPostAttachment.IUpdate;

  // 6) Expect denial: updating attachment under a deleted post must fail
  await TestValidator.error(
    "cannot update attachment when parent post is deleted",
    async () => {
      await api.functional.civicBoard.user.posts.attachments.update(
        connection,
        {
          postId: post.id,
          attachmentId: attachment.id,
          body: updateBody,
        },
      );
    },
  );
}

